1	/**
2	 * Sitewave — PHASE 2 CRM pipeline stage helpers. Pure (no db / next imports) so
3	 * the transition rules are unit-tested and the server action + kanban UI agree.
4	 *
5	 * The pipeline is a simple linear funnel with two terminal states. We allow any
6	 * forward move and a move back one step (an operator correcting a mis-click),
7	 * plus reopening a WON/LOST deal — but we reject nonsense like LEAD -> WON in one
8	 * jump so the funnel stats stay meaningful.
9	 */
10	
11	export const DEAL_STAGES = [
12	  "LEAD",
13	  "CONTACTED",
14	  "DEMO_SENT",
15	  "NEGOTIATING",
16	  "WON",
17	  "LOST",
18	] as const;
19	
20	export type DealStage = (typeof DEAL_STAGES)[number];
21	
22	/** Human labels for the kanban columns (sentence case). */
23	export const STAGE_LABELS: Record<DealStage, string> = {
24	  LEAD: "Lead",
25	  CONTACTED: "Contacted",
26	  DEMO_SENT: "Demo sent",
27	  NEGOTIATING: "Negotiating",
28	  WON: "Won",
29	  LOST: "Lost",
30	};
31	
32	/** The ordered, non-terminal progression a deal walks through. */
33	const PROGRESSION: DealStage[] = ["LEAD", "CONTACTED", "DEMO_SENT", "NEGOTIATING"];
34	
35	export function isDealStage(v: unknown): v is DealStage {
36	  return typeof v === "string" && (DEAL_STAGES as readonly string[]).includes(v);
37	}
38	
39	export function isTerminal(stage: DealStage): boolean {
40	  return stage === "WON" || stage === "LOST";
41	}
42	
43	/**
44	 * Is moving `from` -> `to` a legal transition?
45	 *
46	 * Rules:
47	 *  - staying put is a no-op, always allowed;
48	 *  - from any non-terminal stage you may advance any number of steps forward,
49	 *    step back exactly one, or close the deal (WON / LOST);
50	 *  - a terminal deal (WON / LOST) may be REOPENED to any non-terminal stage, or
51	 *    flipped between WON and LOST;
52	 *  - anything else is rejected.
53	 */
54	export function canTransition(from: DealStage, to: DealStage): boolean {
55	  if (!isDealStage(from) || !isDealStage(to)) return false;
56	  if (from === to) return true;
57	
58	  // Terminal -> reopen to a non-terminal, or WON<->LOST.
59	  if (isTerminal(from)) {
60	    if (!isTerminal(to)) return true;
61	    return true; // WON <-> LOST flip
62	  }
63	
64	  // Non-terminal -> terminal is always allowed (close the deal).
65	  if (isTerminal(to)) return true;
66	
67	  // Non-terminal -> non-terminal: forward any distance, or back exactly one.
68	  const fi = PROGRESSION.indexOf(from);
69	  const ti = PROGRESSION.indexOf(to);
70	  if (fi < 0 || ti < 0) return false;
71	  if (ti > fi) return true; // forward
72	  return fi - ti === 1; // back one step only
73	}
74

1	/**
2	 * Sitewave — PHASE 2 quote math. Pure (no db / next / anthropic imports) so it
3	 * unit-tests cleanly and the server action and the UI compute identical totals.
4	 *
5	 * Money is integer cents throughout — never floats — so rounding is explicit and
6	 * a total can never drift from its line items. Quantities and the tax rate are
7	 * clamped defensively so a hand-crafted POST cannot produce a negative or absurd
8	 * total.
9	 */
10	
11	export type QuoteLine = {
12	  description: string;
13	  quantity: number;
14	  unitCents: number;
15	};
16	
17	export type QuoteTotals = {
18	  /** Sum of quantity * unitCents across all lines, in cents. */
19	  subtotalCents: number;
20	  /** Tax applied to the subtotal, rounded to the nearest cent. */
21	  taxCents: number;
22	  /** subtotalCents + taxCents. */
23	  totalCents: number;
24	};
25	
26	/** Clamp to a non-negative safe integer. */
27	function nonNeg(n: unknown): number {
28	  const v = Math.floor(Number(n));
29	  if (!Number.isFinite(v) || v < 0) return 0;
30	  return Math.min(v, Number.MAX_SAFE_INTEGER);
31	}
32	
33	/** Clamp a whole-percent tax rate into [0, 100]. */
34	export function clampTaxRate(pct: unknown): number {
35	  const v = Math.round(Number(pct));
36	  if (!Number.isFinite(v)) return 0;
37	  return Math.max(0, Math.min(100, v));
38	}
39	
40	/** Total for a single line, in cents (quantity * unitCents, both clamped). */
41	export function lineTotalCents(line: QuoteLine): number {
42	  return nonNeg(line.quantity) * nonNeg(line.unitCents);
43	}
44	
45	/**
46	 * Compute subtotal, tax and total for a set of lines. Deterministic and pure.
47	 * Tax is `round(subtotal * pct / 100)` so it always lands on a whole cent.
48	 */
49	export function quoteTotals(lines: QuoteLine[], taxRatePct: number): QuoteTotals {
50	  const subtotalCents = lines.reduce((sum, l) => sum + lineTotalCents(l), 0);
51	  const pct = clampTaxRate(taxRatePct);
52	  const taxCents = Math.round((subtotalCents * pct) / 100);
53	  return { subtotalCents, taxCents, totalCents: subtotalCents + taxCents };
54	}
55	
56	/** Format integer cents as a currency string (e.g. 125000 -> "$1,250.00"). */
57	export function formatCents(cents: number, currency = "USD"): string {
58	  const safe = Number.isFinite(cents) ? cents : 0;
59	  try {
60	    return new Intl.NumberFormat("en-US", { style: "currency", currency }).format(safe / 100);
61	  } catch {
62	    // Unknown currency code — fall back to a bare number + code.
63	    return `${(safe / 100).toFixed(2)} ${currency}`;
64	  }
65	}
66	
67	/** Parse a user-entered price string ("1,250.50", "$1250") into cents. */
68	export function parsePriceToCents(input: string): number {
69	  const cleaned = String(input ?? "").replace(/[^0-9.]/g, "");
70	  if (!cleaned) return 0;
71	  const value = Number(cleaned);
72	  if (!Number.isFinite(value) || value < 0) return 0;
73	  return Math.round(value * 100);
74	}
