/// Where a review originated. INTERNAL reviews are ones a customer left us
/// directly (or an operator transcribed); the others record the third-party
/// platform the score was verified against, so the homepage badges and the
/// "What our customers say" section only ever surface real, attributable praise.
enum ReviewSource {
  INTERNAL
  GOOGLE
  TRUSTPILOT
  HOSTADVICE
}

/// A customer review, moderated in the admin (/admin/reviews). Only rows with
/// `approved = true` are ever shown publicly; `featured` floats a review to the
/// top of the display section. Aggregations of APPROVED external-source reviews
/// drive the real hero badges (components/marketing/ReviewBadges.tsx) — when none
/// exist yet the badges fall back to the clearly-labelled demo placeholder.
model Review {
  id        String       @id @default(cuid())
  author    String
  role      String?
  rating    Int // 1-5
  body      String
  source    ReviewSource @default(INTERNAL)
  approved  Boolean      @default(false)
  featured  Boolean      @default(false)
  createdAt DateTime     @default(now())

=== HostingTask ===
model HostingTask {
  id        String            @id @default(cuid())
  accountId String
  account   HostingAccount    @relation(fields: [accountId], references: [id], onDelete: Cascade)
  kind      HostingTaskKind
  status    HostingTaskStatus @default(PENDING)
  payload   String? // JSON in
  result    String? // JSON out (may hold a one-time secret until read)
  error     String?
  createdAt DateTime          @default(now())
  updatedAt DateTime          @updatedAt

  @@index([status])
  @@index([accountId])
}

/// A stored backup of an account (home archive + DB dumps) on its node.
model HostingBackup {
  id        String         @id @default(cuid())
  accountId String
  account   HostingAccount @relation(fields: [accountId], references: [id], onDelete: Cascade)
  path      String // absolute path of the archive on the node
  sizeBytes Int            @default(0)
  createdAt DateTime       @default(now())

  @@index([accountId])
}

enum HostingDatabaseStatus {
  PENDING
  ACTIVE
  FAILED
  DELETING
}

/// A MySQL/MariaDB database + its scoped owner user for a hosting account. The
/// generated password is shown ONCE at creation; `passwordEnc` holds it only
/// transiently so the provisioner can apply it, then it is cleared. The DB user
/// is granted rights on THIS database only — the shared-box isolation boundary
/// for data.
model HostingDatabase {
  id          String                @id @default(cuid())
  accountId   String
  account     HostingAccount        @relation(fields: [accountId], references: [id], onDelete: Cascade)
  name        String // real DB name on the box, prefixed by the account username
  dbUser      String
  passwordEnc String? // encrypted; CLEARED once the create step applies it
  status      HostingDatabaseStatus @default(PENDING)
  error       String?
  createdAt   DateTime              @default(now())

  @@unique([accountId, name])
  @@index([accountId])
}

