type ProspectRow = NonNullable<Awaited<ReturnType<typeof db.agencyProspect.findUnique>>>;

/**
 * Core demo generation shared by "Generate demo" and "Scrape & generate". Runs
 * the generator (LLM or fallback), renders guardrailed HTML, persists the demo +
 * a generation log, snapshots the extraction that informed it, and advances the
 * prospect. Never persists a demo missing a mandatory legal guardrail.
 */
async function generateDemoForProspect(
  prospect: ProspectRow,
  opts: { extraction?: ScrapeResult["extraction"]; pastedTextOverride?: string } = {}
): Promise<ActionState> {
  const vertical = prospect.vertical || "dentist";
  const dbVertical = await db.agencyVertical.findUnique({
    where: { slug: vertical },
    include: { templates: { orderBy: { createdAt: "asc" }, take: 1 } },
  });
  const template = dbVertical?.templates[0] ?? null;
  const structure = template ? asTemplateStructure(template.structure) : undefined;
  const slug = slugify(prospect.businessName);
  const pastedSiteText = (opts.pastedTextOverride ?? prospect.pastedSiteText ?? "").slice(0, 6000);

  let ir: SiteIR;
  let genMode = "fallback";
  let genModel = "";
  let genOk = true;
  let genMsg = "";
  try {
    const result = await generateSiteIR({
      businessName: prospect.businessName,
      vertical,
      slug,
      pastedSiteText,
      structure,
    });
    ir = result.ir;
    genMode = result.mode;
    genModel = result.model;
    genOk = result.ok;
    genMsg = result.message;
  } catch (err) {
    await logEvent("error", "agency.demo.generate", { message: String(err), prospectId: prospect.id });
    return { error: "Generation failed. Please try again." };
  }

  const rendered = renderSiteHtml(ir);
  if (!rendered.guardrailsOk) {
    await logEvent("error", "agency.demo.guardrails", { prospectId: prospect.id, message: "guardrail assertion failed" });
    return { error: "Render failed a legal guardrail check and was not saved." };
  }

  try {
    const demo = await db.agencyDemoSite.create({
      data: {
        prospectId: prospect.id,
        templateId: template?.id ?? null,
        siteIR: ir as unknown as Prisma.InputJsonValue,
        renderedHtml: rendered.html,
        extractionJson: (opts.extraction ?? {}) as unknown as Prisma.InputJsonValue,
        slug,
        status: "GENERATED",
        noindex: true,
      },
    });
    await db.agencyGenerationLog.create({
      data: { demoId: demo.id, mode: genMode, model: genModel, ok: genOk, message: genMsg.slice(0, 500) },
    });
    await db.agencyActivity.create({
      data: {
        prospectId: prospect.id,
        kind: "DEMO",
        body: `Generated demo (${genMode})${opts.extraction ? " from scrape" : ""}.`,
        meta: { demoId: demo.id, mode: genMode } as Prisma.InputJsonValue,
      },
    });
    if (prospect.status === "PROSPECT") {
      await db.agencyProspect.update({ where: { id: prospect.id }, data: { status: "GENERATED" } });
    }
  } catch (err) {
    await logEvent("error", "agency.demo.persist", { message: String(err), prospectId: prospect.id });
    return { error: "Could not save the generated demo." };
  }

  revalidatePath("/admin/agency/demos");
  revalidatePath("/admin/agency/prospects");
  revalidatePath(`/admin/agency/prospects/${prospect.id}`);
  revalidatePath("/admin/agency");
  return { ok: true };
}

/**
 * Generate a spec-site demo for a prospect from stored data only. No network to
 * the prospect's site; no deploy.
 */
export async function generateDemo(prospectId: string): Promise<ActionState> {
  await requireArea("platform");
  const prospect = await db.agencyProspect.findUnique({ where: { id: prospectId } });
  if (!prospect) return { error: "Prospect not found." };
  return generateDemoForProspect(prospect);
}

/**
 * OPERATOR-TRIGGERED scrape of the prospect's currentSiteUrl, then generate a
 * demo from what was extracted. The scrape is SSRF-safe (lib/agency/scrape.ts):
 * https/http only, private/reserved IPs refused, per-hop redirect re-validation,
 * size + time caps. On any refusal/failure the scrape result is still recorded and
 * generation proceeds from whatever stored text exists (graceful degrade).
 */
export async function scrapeAndGenerate(prospectId: string): Promise<ActionState> {
  await requireArea("platform");
  const prospect = await db.agencyProspect.findUnique({ where: { id: prospectId } });
  if (!prospect) return { error: "Prospect not found." };
  if (!prospect.currentSiteUrl) {
    return { error: "This prospect has no current site URL to scrape." };
  }

  const result = await scrapeSite(prospect.currentSiteUrl);
  const status = result.ok ? "ok" : `refused: ${result.error}`.slice(0, 200);
  try {
    await db.agencyProspect.update({
      where: { id: prospect.id },
      data: {
        scrapeJson: result as unknown as Prisma.InputJsonValue,
        scrapeStatus: status,
        scrapedAt: new Date(),
      },
    });
    await db.agencyActivity.create({
      data: {
        prospectId: prospect.id,
        kind: "SCRAPE",
        body: result.ok
          ? `Scraped ${result.finalUrl || prospect.currentSiteUrl} (${result.bytes} bytes).`
          : `Scrape refused/failed: ${result.error}`,
        meta: { ok: result.ok, status: result.status, finalUrl: result.finalUrl } as Prisma.InputJsonValue,
      },
    });
  } catch (err) {
    await logEvent("error", "agency.scrape.persist", { message: String(err), prospectId });
  }
  await logEvent("info", "agency.scrape", { prospectId, ok: result.ok, host: prospect.currentSiteUrl });

  const pasted = result.ok
    ? [prospect.pastedSiteText, extractionToPastedText(result.extraction)].filter(Boolean).join("\n\n")
    : prospect.pastedSiteText;

  const gen = await generateDemoForProspect(prospect, {
    extraction: result.ok ? result.extraction : undefined,
    pastedTextOverride: pasted,
  });
  if (gen.error) return gen;
  return {
    ok: true,
    error: result.ok
      ? undefined
      : `Demo generated, but the scrape was skipped (${result.error}).`,
  };
}

/**
 * Deploy a demo to its subdomain. GATED. Builds the static bundle (pure), then:
 *  - default (Setting agency_deploy_enabled off): records DEPLOYED_STUB with the
 *    intended host + bundle size. NOTHING is provisioned;
 *  - enabled: enqueues a REAL deploy (status DEPLOYING, mode "real"). No live
 *    infra is touched by this build — it records intent for a future provisioner.
 */
export async function deployDemo(demoId: string): Promise<ActionState> {
  await requireArea("platform");
  const demo = await db.agencyDemoSite.findUnique({
    where: { id: demoId },
    select: { id: true, slug: true, renderedHtml: true, prospectId: true },
  });
  if (!demo) return { error: "Demo not found." };

  const bundle = buildDeployBundle({ slug: demo.slug, renderedHtml: demo.renderedHtml });
  const enabled = await getSettingBool("agency_deploy_enabled");

  try {
    if (enabled) {
      await db.agencyDemoSite.update({
        where: { id: demo.id },
        data: {
          status: "DEPLOYING",
          deployMode: "real",
          intendedHost: bundle.intendedHost,
          bundleBytes: bundle.bytes,
          deployedAt: new Date(),
        },
      });
      await db.agencyActivity.create({
        data: {
          prospectId: demo.prospectId,
          kind: "SYSTEM",
          body: `Real deploy enqueued for ${bundle.intendedHost} (${bundle.bytes} bytes).`,
          meta: { demoId: demo.id, mode: "real", host: bundle.intendedHost } as Prisma.InputJsonValue,
        },
      });
      await logEvent("info", "agency.demo.deploy_real_enqueued", { demoId, host: bundle.intendedHost, bytes: bundle.bytes });
    } else {
      await db.agencyDemoSite.update({
        where: { id: demo.id },
        data: {
          status: "DEPLOYED_STUB",
          deployMode: "stub",
          intendedHost: bundle.intendedHost,
          bundleBytes: bundle.bytes,
          deployedAt: new Date(),
        },
      });
      await db.agencyActivity.create({
        data: {
          prospectId: demo.prospectId,
          kind: "SYSTEM",
          body: `Deploy stub recorded for ${bundle.intendedHost} (${bundle.bytes} bytes).`,
          meta: { demoId: demo.id, mode: "stub", host: bundle.intendedHost } as Prisma.InputJsonValue,
        },
      });
      await logEvent("info", "agency.demo.deploy_stub", { demoId, host: bundle.intendedHost, bytes: bundle.bytes });
    }
  } catch (err) {
    await logEvent("error", "agency.demo.deploy", { message: String(err), demoId });
    return { error: "Could not record the deploy." };
  }

  revalidatePath("/admin/agency/demos");
  revalidatePath("/admin/agency");
  return { ok: true };
}

/** Backwards-compatible alias — the deploy action is now gated (see deployDemo). */
export async function deployDemoStub(demoId: string): Promise<ActionState> {
  return deployDemo(demoId);
}

// ---------------------------------------------------------------------------
// CRM pipeline — stage transitions, activity log, deal value.
// ---------------------------------------------------------------------------

/**
 * Move a prospect to a new pipeline stage. Rejects illegal jumps (canTransition),
 * records a STAGE_CHANGE activity, and — on WON — ensures an AgencyClient exists.
 */
export async function moveProspectStage(prospectId: string, toStage: string): Promise<ActionState> {
  await requireArea("platform");
  if (!isDealStage(toStage)) return { error: "Invalid stage." };
  const prospect = await db.agencyProspect.findUnique({
    where: { id: prospectId },
    include: { client: { select: { id: true } } },
  });
  if (!prospect) return { error: "Prospect not found." };

  const from = prospect.stage as DealStage;
  const to = toStage as DealStage;
  if (from === to) return { ok: true };
  if (!canTransition(from, to)) {
    return { error: `Cannot move ${from} → ${to} in one step.` };
  }

  try {
    await db.agencyProspect.update({ where: { id: prospectId }, data: { stage: to } });
    await db.agencyActivity.create({
      data: {
        prospectId,
        kind: "STAGE_CHANGE",
        body: `Stage ${from} → ${to}.`,
        meta: { from, to } as Prisma.InputJsonValue,
      },
    });
    if (to === "WON" && !prospect.client) {
      await createClientForProspect(prospect.id, prospect.businessName, prospect.contactEmail);
    }
  } catch (err) {
    await logEvent("error", "agency.stage.move", { message: String(err), prospectId });
    return { error: "Could not update the stage." };
  }

  revalidatePath("/admin/agency/pipeline");
  revalidatePath(`/admin/agency/prospects/${prospectId}`);
  revalidatePath("/admin/agency");
  return { ok: true };
}

const noteSchema = z.object({ body: z.string().trim().min(1, "Write a note first.").max(4000) });

export async function addActivityNote(prospectId: string, body: string): Promise<ActionState> {
  await requireArea("platform");
  const parsed = noteSchema.safeParse({ body });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid note." };
  const exists = await db.agencyProspect.findUnique({ where: { id: prospectId }, select: { id: true } });
  if (!exists) return { error: "Prospect not found." };
  await db.agencyActivity.create({ data: { prospectId, kind: "NOTE", body: parsed.data.body } });
  revalidatePath(`/admin/agency/prospects/${prospectId}`);
  return { ok: true };
}

export async function setDealValue(prospectId: string, value: string): Promise<ActionState> {
  await requireArea("platform");
  const cents = parsePriceToCents(value);
  await db.agencyProspect.update({ where: { id: prospectId }, data: { dealValueCents: cents } }).catch(() => null);
  revalidatePath("/admin/agency/pipeline");
  revalidatePath(`/admin/agency/prospects/${prospectId}`);
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Clients + quotes (WON conversion).
// ---------------------------------------------------------------------------

/** Create a client + a starter DRAFT quote for a prospect. Internal helper. */
async function createClientForProspect(
  prospectId: string,
  businessName: string,
  contactEmail: string | null
): Promise<string> {
  const client = await db.agencyClient.create({
    data: {
      prospectId,
      businessName,
      contactEmail: contactEmail ?? null,
      quotes: {
        create: {
          title: "Website project",
          status: "DRAFT",
          lineItems: {
            create: [
              { description: "Custom website design & build", quantity: 1, unitCents: 250000, sortOrder: 0 },
              { description: "Hosting & maintenance (monthly)", quantity: 12, unitCents: 3000, sortOrder: 1 },
            ],
          },
        },
      },
    },
  });
  await db.agencyActivity.create({
    data: { prospectId, kind: "CONVERT", body: "Converted to client with a starter quote." },
  });
  return client.id;
}

/**
 * Convert a WON prospect into a client (idempotent). Also flips the CRM stage to
 * WON if it is not already terminal, so "Convert" works from a detail page.
 */
export async function convertToClient(prospectId: string): Promise<ActionState> {
  await requireArea("platform");
  const prospect = await db.agencyProspect.findUnique({
    where: { id: prospectId },
    include: { client: { select: { id: true } } },
  });
  if (!prospect) return { error: "Prospect not found." };
  if (prospect.client) return { error: "This prospect is already a client." };

  try {
    if (prospect.stage !== "WON") {
      await db.agencyProspect.update({ where: { id: prospectId }, data: { stage: "WON" } });
      await db.agencyActivity.create({
        data: { prospectId, kind: "STAGE_CHANGE", body: `Stage ${prospect.stage} → WON (on convert).`, meta: { from: prospect.stage, to: "WON" } as Prisma.InputJsonValue },
      });
    }
    await createClientForProspect(prospect.id, prospect.businessName, prospect.contactEmail);
  } catch (err) {
    await logEvent("error", "agency.convert", { message: String(err), prospectId });
    return { error: "Could not convert this prospect." };
  }
  revalidatePath(`/admin/agency/prospects/${prospectId}`);
  revalidatePath("/admin/agency/pipeline");
  return { ok: true };
}

const lineSchema = z.object({
  description: z.string().trim().min(1, "A description is required.").max(200),
  quantity: z.string().trim().default("1"),
  price: z.string().trim().default("0"),
});

export async function addQuoteLine(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const quoteId = String(formData.get("quoteId") ?? "");
  const parsed = lineSchema.safeParse({
    description: formData.get("description"),
    quantity: formData.get("quantity") ?? "1",
    price: formData.get("price") ?? "0",
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid line." };
  const quote = await db.agencyQuote.findUnique({ where: { id: quoteId }, select: { id: true, clientId: true } });
  if (!quote) return { error: "Quote not found." };

  const qtyNum = Math.max(1, Math.min(100000, Math.floor(Number(parsed.data.quantity)) || 1));
  const count = await db.agencyQuoteLineItem.count({ where: { quoteId } });
  await db.agencyQuoteLineItem.create({
    data: {
      quoteId,
      description: parsed.data.description,
      quantity: qtyNum,
      unitCents: parsePriceToCents(parsed.data.price),
      sortOrder: count,
    },
  });
  await revalidateClient(quote.clientId);
  return { ok: true };
}

export async function deleteQuoteLine(id: string): Promise<ActionState> {
  await requireArea("platform");
  const line = await db.agencyQuoteLineItem.findUnique({ where: { id }, select: { quote: { select: { clientId: true } } } });
  await db.agencyQuoteLineItem.delete({ where: { id } }).catch(() => null);
  if (line?.quote.clientId) await revalidateClient(line.quote.clientId);
  return { ok: true };
}

const QUOTE_STATUSES = ["DRAFT", "SENT", "ACCEPTED", "DECLINED"] as const;

export async function setQuoteStatus(quoteId: string, status: string): Promise<ActionState> {
  await requireArea("platform");
  if (!QUOTE_STATUSES.includes(status as (typeof QUOTE_STATUSES)[number])) return { error: "Invalid status." };
  const quote = await db.agencyQuote
    .update({ where: { id: quoteId }, data: { status: status as (typeof QUOTE_STATUSES)[number] }, select: { clientId: true } })
    .catch(() => null);
  if (quote) await revalidateClient(quote.clientId);
  return { ok: true };
}

export async function setQuoteTaxRate(quoteId: string, pct: string): Promise<ActionState> {
  await requireArea("platform");
  const rate = clampTaxRate(Number(pct));
  const quote = await db.agencyQuote.update({ where: { id: quoteId }, data: { taxRatePct: rate }, select: { clientId: true } }).catch(() => null);
  if (quote) await revalidateClient(quote.clientId);
  return { ok: true };
}

export async function createQuote(clientId: string): Promise<ActionState> {
  await requireArea("platform");
  const client = await db.agencyClient.findUnique({ where: { id: clientId }, select: { id: true } });
  if (!client) return { error: "Client not found." };
  await db.agencyQuote.create({ data: { clientId, title: "New quote", status: "DRAFT" } });
  await revalidateClient(clientId);
  return { ok: true };
}

export async function deleteQuote(quoteId: string): Promise<ActionState> {
  await requireArea("platform");
  const quote = await db.agencyQuote.findUnique({ where: { id: quoteId }, select: { clientId: true } });
  await db.agencyQuote.delete({ where: { id: quoteId } }).catch(() => null);
  if (quote) await revalidateClient(quote.clientId);
  return { ok: true };
}

async function revalidateClient(clientId: string): Promise<void> {
  const c = await db.agencyClient.findUnique({ where: { id: clientId }, select: { prospectId: true } });
  if (c) revalidatePath(`/admin/agency/prospects/${c.prospectId}`);
}

