/** A stage <select> that moves a prospect between pipeline columns. */
export function StageMover({ id, stage }: { id: string; stage: DealStage }) {
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  return (
    <span className="inline-flex flex-col">
      <select
        defaultValue={stage}
        disabled={pending}
        className="input h-8 py-0 text-xs"
        onChange={(e) => {
          const next = e.target.value;
          setErr(null);
          start(async () => {
            const r = await moveProspectStage(id, next);
            if (r?.error) setErr(r.error);
          });
        }}
      >
        {DEAL_STAGES.map((s) => (
          <option key={s} value={s}>
            {STAGE_LABELS[s]}
          </option>
        ))}
      </select>
      {err && <span className="mt-1 text-[11px] text-red-400">{err}</span>}
    </span>
  );
}

export function ScrapeGenerateButton({ id }: { id: string }) {
  return (
    <ActionButton
      run={() => scrapeAndGenerate(id)}
      confirm="Fetch this prospect's current site (operator-triggered, SSRF-safe) and generate a demo from it?"
      className="btn-primary text-xs"
      title="SSRF-safe single-page scrape, then generate"
    >
      Scrape &amp; generate
    </ActionButton>
  );
}

export function ConvertButton({ id }: { id: string }) {
  return (
    <ActionButton
      run={() => convertToClient(id)}
      confirm="Convert this prospect to a client (marks WON and creates a starter quote)?"
      className="btn-primary text-xs"
    >
      Convert to client
    </ActionButton>
  );
}

export function DealValueForm({ id, cents }: { id: string; cents: number }) {
  const [pending, start] = useTransition();
  const [val, setVal] = useState((cents / 100).toFixed(2));
  return (
    <form
      className="flex items-center gap-2"
      onSubmit={(e) => {
        e.preventDefault();
        start(async () => {
          await setDealValue(id, val);
        });
      }}
    >
      <span className="text-xs text-slate-500">Deal value $</span>
      <input value={val} onChange={(e) => setVal(e.target.value)} className="input h-8 w-28 py-0 text-xs" inputMode="decimal" />
      <button type="submit" disabled={pending} className="btn-ghost text-xs">
        {pending ? "Saving…" : "Save"}
      </button>
    </form>
  );
}

export function NoteForm({ id }: { id: string }) {
  const [pending, start] = useTransition();
  const [body, setBody] = useState("");
  const [err, setErr] = useState<string | null>(null);
  return (
    <form
      className="space-y-2"
      onSubmit={(e) => {
        e.preventDefault();
        setErr(null);
        start(async () => {
          const r = await addActivityNote(id, body);
          if (r?.error) setErr(r.error);
          else setBody("");
        });
      }}
    >
      <textarea value={body} onChange={(e) => setBody(e.target.value)} className="input min-h-[60px] text-sm" placeholder="Add a note to the activity log…" />
      {err && <p className="text-[11px] text-red-400">{err}</p>}
      <button type="submit" disabled={pending} className="btn-primary text-xs">
        {pending ? "Adding…" : "Add note"}
      </button>
    </form>
  );
}

export function CreateQuoteButton({ clientId }: { clientId: string }) {
  return (
    <ActionButton run={() => createQuote(clientId)} className="btn-ghost text-xs">
