    >
      <span className="text-xs text-slate-500">Tax %</span>
      <input value={val} onChange={(e) => setVal(e.target.value)} className="input h-8 w-16 py-0 text-xs" inputMode="numeric" />
      <button type="submit" disabled={pending} className="btn-ghost text-xs">
        {pending ? "…" : "Set"}
      </button>
    </form>
  );
}

export function AddLineForm({ quoteId }: { quoteId: string }) {
  const [state, action] = useActionState(addQuoteLine, EMPTY);
  const ref = useRef<HTMLFormElement>(null);
  useEffect(() => {
    if (state?.ok) ref.current?.reset();
  }, [state]);
  return (
    <form ref={ref} action={action} className="flex flex-wrap items-end gap-2">
      <input type="hidden" name="quoteId" value={quoteId} />
      <div className="grow">
        <label className="label">Description</label>
        <input name="description" className="input h-8 py-0 text-xs" placeholder="Line item" required />
      </div>
      <div>
        <label className="label">Qty</label>
        <input name="quantity" className="input h-8 w-16 py-0 text-xs" defaultValue="1" inputMode="numeric" />
      </div>
      <div>
        <label className="label">Unit $</label>
        <input name="price" className="input h-8 w-24 py-0 text-xs" defaultValue="0" inputMode="decimal" />
      </div>
      <button type="submit" className="btn-ghost text-xs">
        Add line
      </button>
      {state?.error && !state.ok && <span className="w-full text-[11px] text-red-400">{state.error}</span>}
    </form>
  );
}

export function LineDeleteButton({ id }: { id: string }) {
  return (
    <ActionButton run={() => deleteQuoteLine(id)} className="btn-ghost text-[11px] text-red-400">
      Remove
    </ActionButton>
  );
}

