import Link from "next/link";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, EmptyState, fmtMoney } from "@/components/ui/primitives";
import { StageMover } from "@/components/admin/agency/Controls";
import { DEAL_STAGES, STAGE_LABELS, type DealStage } from "@/lib/agency/pipeline";

export const dynamic = "force-dynamic";

const OPEN_STAGES: DealStage[] = ["LEAD", "CONTACTED", "DEMO_SENT", "NEGOTIATING"];

export default async function AgencyPipeline() {
  await requireArea("platform");

  const prospects = await db.agencyProspect.findMany({
    orderBy: { createdAt: "desc" },
    select: {
      id: true,
      businessName: true,
      vertical: true,
      stage: true,
      dealValueCents: true,
      _count: { select: { demos: true, activities: true } },
    },
    take: 1000,
  });

  const byStage: Record<string, typeof prospects> = {};
  for (const s of DEAL_STAGES) byStage[s] = [];
  for (const p of prospects) (byStage[p.stage] ??= []).push(p);

  const openValue = prospects
    .filter((p) => OPEN_STAGES.includes(p.stage as DealStage))
    .reduce((sum, p) => sum + p.dealValueCents, 0);
  const wonValue = byStage.WON.reduce((sum, p) => sum + p.dealValueCents, 0);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Pipeline"
        sub="Deal stages from lead to won. Move a card with its stage selector; open a card for its activity log, scrape result, demos, and (once won) client + quotes."
      />

      <div className="grid gap-4 sm:grid-cols-3">
        <div className="card">
          <div className="text-xs text-slate-500">Open deals</div>
          <div className="mt-1 text-2xl font-bold">{prospects.filter((p) => OPEN_STAGES.includes(p.stage as DealStage)).length}</div>
        </div>
        <div className="card">
          <div className="text-xs text-slate-500">Open pipeline value</div>
          <div className="mt-1 text-2xl font-bold">{fmtMoney(openValue)}</div>
        </div>
        <div className="card">
          <div className="text-xs text-slate-500">Won value</div>
          <div className="mt-1 text-2xl font-bold">{fmtMoney(wonValue)}</div>
        </div>
      </div>

      {prospects.length === 0 ? (
        <div className="card">
          <EmptyState title="No prospects yet" sub="Add prospects on the Prospects tab to start the pipeline." />
        </div>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-6">
          {DEAL_STAGES.map((stage) => {
            const cards = byStage[stage] ?? [];
            const colValue = cards.reduce((s, c) => s + c.dealValueCents, 0);
            return (
              <div key={stage} className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
                <div className="mb-3 flex items-center justify-between">
                  <span className="section-label">{STAGE_LABELS[stage]}</span>
                  <span className="text-xs text-slate-500">{cards.length}</span>
                </div>
                {colValue > 0 && <div className="mb-2 text-[11px] text-slate-500">{fmtMoney(colValue)}</div>}
                <div className="space-y-2">
                  {cards.map((p) => (
                    <div key={p.id} className="rounded-lg border border-white/[0.06] bg-white/[0.03] p-3">
                      <Link href={`/admin/agency/prospects/${p.id}`} className="font-medium text-white hover:underline">
                        {p.businessName}
                      </Link>
                      <div className="mt-0.5 text-xs text-slate-500">
                        {p.vertical || "—"} · {fmtMoney(p.dealValueCents)}
                      </div>
                      <div className="mt-1 text-[11px] text-slate-600">
                        {p._count.demos} demo{p._count.demos === 1 ? "" : "s"} · {p._count.activities} activit
                        {p._count.activities === 1 ? "y" : "ies"}
                      </div>
                      <div className="mt-2">
                        <StageMover id={p.id} stage={p.stage as DealStage} />
                      </div>
                    </div>
                  ))}
                  {cards.length === 0 && <p className="text-xs text-slate-600">—</p>}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, EmptyState, timeAgo } from "@/components/ui/primitives";
import {
  StageMover,
  DealValueForm,
  NoteForm,
  ScrapeGenerateButton,
  ConvertButton,
  CreateQuoteButton,
  DeleteQuoteButton,
  QuoteStatusSelect,
  TaxRateForm,
  AddLineForm,
  LineDeleteButton,
} from "@/components/admin/agency/Controls";
import { STAGE_LABELS, type DealStage } from "@/lib/agency/pipeline";
import { quoteTotals, formatCents } from "@/lib/agency/quote";

export const dynamic = "force-dynamic";

const ACTIVITY_TONE: Record<string, "brand" | "green" | "amber" | "slate" | "red"> = {
  NOTE: "slate",
  STAGE_CHANGE: "brand",
  SCRAPE: "amber",
  DEMO: "brand",
  QUOTE: "green",
  CONVERT: "green",
  SYSTEM: "slate",
};

export default async function ProspectDetail({ params }: { params: Promise<{ id: string }> }) {
  await requireArea("platform");
  const { id } = await params;

  const prospect = await db.agencyProspect.findUnique({
    where: { id },
    include: {
      demos: { orderBy: { createdAt: "desc" } },
      activities: { orderBy: { createdAt: "desc" }, take: 100 },
      client: { include: { quotes: { include: { lineItems: { orderBy: { sortOrder: "asc" } } }, orderBy: { createdAt: "desc" } } } },
    },
  });
  if (!prospect) notFound();

  const scrape = prospect.scrapeJson as
    | { ok?: boolean; finalUrl?: string; bytes?: number; extraction?: Record<string, unknown> }
    | null;
  const extraction = (scrape?.extraction ?? null) as
    | { businessName?: string; tagline?: string; services?: string[]; emails?: string[]; phones?: string[]; colorHint?: string }
    | null;

  return (
    <div className="space-y-6">
      <PageHeader
        title={prospect.businessName}
        sub={`${prospect.vertical || "no vertical"} · status ${prospect.status.toLowerCase()}`}
      />
      <Link href="/admin/agency/pipeline" className="text-xs text-brand-300 hover:underline">
        ← Back to pipeline
      </Link>

      {/* Deal controls */}
      <div className="card space-y-4">
        <p className="section-label">Deal</p>
        <div className="flex flex-wrap items-center gap-6">
          <div>
            <div className="mb-1 text-xs text-slate-500">Stage</div>
            <StageMover id={prospect.id} stage={prospect.stage as DealStage} />
          </div>
          <DealValueForm id={prospect.id} cents={prospect.dealValueCents} />
          {!prospect.client && <ConvertButton id={prospect.id} />}
        </div>
        {prospect.contactEmail && <p className="text-xs text-slate-500">Contact: {prospect.contactEmail}</p>}
        {prospect.currentSiteUrl && (
          <p className="text-xs text-slate-500">
            Current site: <span className="font-mono">{prospect.currentSiteUrl}</span>
          </p>
        )}
      </div>

      {/* Scrape + generate */}
      <div className="card space-y-3">
        <div className="flex items-center justify-between">
          <p className="section-label">Site scrape (operator-triggered, SSRF-safe)</p>
          {prospect.currentSiteUrl && <ScrapeGenerateButton id={prospect.id} />}
        </div>
        {!prospect.currentSiteUrl && (
          <p className="text-xs text-slate-500">No current site URL on this prospect — add one to enable scraping.</p>
        )}
        {prospect.scrapedAt && (
          <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3 text-sm">
            <div className="flex items-center gap-2">
              <Badge tone={scrape?.ok ? "green" : "red"}>{scrape?.ok ? "ok" : "refused/failed"}</Badge>
              <span className="text-xs text-slate-500">
                {prospect.scrapeStatus} · {timeAgo(prospect.scrapedAt)}
              </span>
            </div>
            {extraction && scrape?.ok && (
              <dl className="mt-3 grid gap-2 text-xs sm:grid-cols-2">
                {extraction.businessName && <div><dt className="text-slate-500">Name</dt><dd className="text-slate-300">{extraction.businessName}</dd></div>}
                {extraction.tagline && <div><dt className="text-slate-500">Tagline</dt><dd className="text-slate-300">{extraction.tagline}</dd></div>}
                {extraction.services?.length ? <div className="sm:col-span-2"><dt className="text-slate-500">Services</dt><dd className="text-slate-300">{extraction.services.slice(0, 8).join(", ")}</dd></div> : null}
                {extraction.emails?.length ? <div><dt className="text-slate-500">Emails</dt><dd className="text-slate-300">{extraction.emails.join(", ")}</dd></div> : null}
                {extraction.phones?.length ? <div><dt className="text-slate-500">Phones</dt><dd className="text-slate-300">{extraction.phones.join(", ")}</dd></div> : null}
                {extraction.colorHint ? <div><dt className="text-slate-500">Colour hint</dt><dd className="font-mono text-slate-300">{extraction.colorHint}</dd></div> : null}
              </dl>
            )}
          </div>
        )}
      </div>

      {/* Demos */}
      <div className="card space-y-3">
        <p className="section-label">Demos ({prospect.demos.length})</p>
        {prospect.demos.length === 0 ? (
          <p className="text-xs text-slate-500">None yet — generate one above or from the Prospects tab.</p>
        ) : (
          <ul className="space-y-2">
            {prospect.demos.map((d) => (
              <li key={d.id} className="flex items-center justify-between rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
                <span className="font-mono text-xs text-slate-400">{d.intendedHost || `${d.slug}.agency.revsports.ca`}</span>
                <span className="flex items-center gap-3">
                  <Badge tone="slate">{d.status.toLowerCase().replace(/_/g, " ")}</Badge>
                  <a href={`/api/agency/demo/${d.id}/preview`} target="_blank" rel="noreferrer" className="btn-ghost text-xs">Preview</a>
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Client + quotes */}
      {prospect.client && (
        <div className="card space-y-4">
          <div className="flex items-center justify-between">
            <p className="section-label">Client · {prospect.client.projectName}</p>
            <CreateQuoteButton clientId={prospect.client.id} />
          </div>
          {prospect.client.quotes.length === 0 ? (
            <EmptyState title="No quotes" sub="Create one to add line items." />
          ) : (
            prospect.client.quotes.map((q) => {
              const totals = quoteTotals(
                q.lineItems.map((l) => ({ description: l.description, quantity: l.quantity, unitCents: l.unitCents })),
                q.taxRatePct
              );
              return (
                <div key={q.id} className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-4">
                  <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
                    <span className="font-medium text-white">{q.title}</span>
                    <span className="flex items-center gap-3">
                      <QuoteStatusSelect quoteId={q.id} status={q.status} />
                      <TaxRateForm quoteId={q.id} pct={q.taxRatePct} />
                      <DeleteQuoteButton quoteId={q.id} />
                    </span>
                  </div>
                  <table className="table-shell w-full">
                    <thead>
                      <tr>
                        <th>Description</th>
                        <th className="text-right">Qty</th>
                        <th className="text-right">Unit</th>
                        <th className="text-right">Line</th>
                        <th></th>
                      </tr>
                    </thead>
                    <tbody>
                      {q.lineItems.map((l) => (
                        <tr key={l.id}>
                          <td>{l.description}</td>
                          <td className="text-right">{l.quantity}</td>
                          <td className="text-right">{formatCents(l.unitCents, q.currency)}</td>
                          <td className="text-right">{formatCents(l.quantity * l.unitCents, q.currency)}</td>
                          <td className="text-right"><LineDeleteButton id={l.id} /></td>
                        </tr>
                      ))}
                      {q.lineItems.length === 0 && (
                        <tr><td colSpan={5} className="text-xs text-slate-500">No line items yet.</td></tr>
                      )}
                    </tbody>
                    <tfoot>
                      <tr><td colSpan={3} className="text-right text-slate-500">Subtotal</td><td className="text-right">{formatCents(totals.subtotalCents, q.currency)}</td><td></td></tr>
                      <tr><td colSpan={3} className="text-right text-slate-500">Tax ({q.taxRatePct}%)</td><td className="text-right">{formatCents(totals.taxCents, q.currency)}</td><td></td></tr>
                      <tr><td colSpan={3} className="text-right font-semibold text-white">Total</td><td className="text-right font-semibold text-white">{formatCents(totals.totalCents, q.currency)}</td><td></td></tr>
                    </tfoot>
                  </table>
                  <div className="mt-3">
                    <AddLineForm quoteId={q.id} />
                  </div>
                </div>
              );
            })
          )}
        </div>
      )}

      {/* Activity log */}
      <div className="card space-y-4">
        <p className="section-label">Activity</p>
        <NoteForm id={prospect.id} />
        {prospect.activities.length === 0 ? (
          <p className="text-xs text-slate-500">No activity yet.</p>
        ) : (
          <ul className="space-y-2">
            {prospect.activities.map((a) => (
              <li key={a.id} className="flex items-start gap-3 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
                <Badge tone={ACTIVITY_TONE[a.kind] ?? "slate"}>{a.kind.toLowerCase().replace(/_/g, " ")}</Badge>
                <span className="grow text-slate-300">{a.body}</span>
                <span className="shrink-0 text-[11px] text-slate-600">{timeAgo(a.createdAt)}</span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

import { test } from "node:test";
import assert from "node:assert/strict";
import http from "node:http";
import { once } from "node:events";
import {
  isBlockedIPv4,
  isBlockedIPv6,
  isBlockedIp,
  parseHttpUrl,
  assertHostPublic,
  extractFromHtml,
  extractionToPastedText,
  scrapeSite,
  MAX_BYTES,
  TIMEOUT_MS,
  MAX_REDIRECTS,
} from "../lib/agency/scrape.ts";
import { canTransition, isDealStage, isTerminal, DEAL_STAGES } from "../lib/agency/pipeline.ts";
import {
  quoteTotals,
  clampTaxRate,
  lineTotalCents,
  parsePriceToCents,
  formatCents,
} from "../lib/agency/quote.ts";
import { buildDeployBundle, DEMO_ROBOTS_TXT } from "../lib/agency/deploy.ts";

/* ================================================================== *
 * 1. SSRF guard — private / reserved IPs are refused
 * ================================================================== */

test("isBlockedIPv4 refuses every private/reserved range", () => {
  const blocked = [
    "0.0.0.0",
    "10.0.0.1",
    "10.255.255.255",
    "127.0.0.1",
    "127.1.2.3",
    "169.254.169.254", // cloud metadata
    "169.254.0.1",
    "172.16.0.1",
    "172.31.255.255",
    "192.168.0.1",
    "192.168.1.1",
    "100.64.0.1", // CGNAT
    "192.0.0.1",
    "198.18.0.1",
    "224.0.0.1", // multicast
    "240.0.0.1", // reserved
    "255.255.255.255",
  ];
  for (const ip of blocked) assert.equal(isBlockedIPv4(ip), true, `${ip} must be blocked`);
});

test("isBlockedIPv4 allows public addresses", () => {
  for (const ip of ["8.8.8.8", "1.1.1.1", "172.15.0.1", "172.32.0.1", "192.167.0.1", "100.63.0.1", "13.107.42.14"]) {
    assert.equal(isBlockedIPv4(ip), false, `${ip} must be allowed`);
  }
});

test("isBlockedIPv6 refuses loopback/ULA/link-local/mapped-private", () => {
  const blocked = [
    "::1", // loopback
    "::", // unspecified
    "fc00::1", // ULA
    "fd12:3456::1", // ULA
    "fe80::1", // link-local
    "ff02::1", // multicast
    "::ffff:127.0.0.1", // v4-mapped loopback
    "::ffff:10.0.0.1", // v4-mapped private
    "64:ff9b::169.254.169.254", // NAT64 metadata
  ];
  for (const ip of blocked) assert.equal(isBlockedIPv6(ip), true, `${ip} must be blocked`);
});

test("isBlockedIPv6 allows public v6 + v4-mapped public", () => {
  assert.equal(isBlockedIPv6("2606:4700:4700::1111"), false); // cloudflare
  assert.equal(isBlockedIPv6("::ffff:8.8.8.8"), false); // v4-mapped public
});

test("isBlockedIp refuses garbage and routes by family", () => {
  assert.equal(isBlockedIp("not-an-ip"), true);
  assert.equal(isBlockedIp("127.0.0.1"), true);
  assert.equal(isBlockedIp("::1"), true);
  assert.equal(isBlockedIp("8.8.8.8"), false);
});

/* ================================================================== *
 * 2. URL scheme + host validation
 * ================================================================== */

test("parseHttpUrl accepts http/https and rejects other schemes", () => {
  assert.equal(parseHttpUrl("https://example.com/path").hostname, "example.com");
  assert.equal(parseHttpUrl("http://example.com").protocol, "http:");
  for (const bad of ["file:///etc/passwd", "gopher://x", "ftp://x", "data:text/html,x", "javascript:alert(1)"]) {
    assert.throws(() => parseHttpUrl(bad), /Refused|valid/i, `${bad} must be refused`);
  }
});

test("assertHostPublic refuses IP-literal private hosts (no DNS)", async () => {
  for (const host of ["127.0.0.1", "169.254.169.254", "10.0.0.5", "192.168.1.1", "::1", "[::1]", "fc00::1"]) {
    await assert.rejects(assertHostPublic(host), /private|reserved/i, `${host} must be refused`);
  }
});

test("assertHostPublic refuses local hostnames without resolving", async () => {
  for (const host of ["localhost", "foo.localhost", "printer.local"]) {
    await assert.rejects(assertHostPublic(host), /local/i, `${host} must be refused`);
  }
});

test("assertHostPublic accepts a public IP literal", async () => {
  const addrs = await assertHostPublic("8.8.8.8");
  assert.deepEqual(addrs, ["8.8.8.8"]);
});

/* ================================================================== *
 * 3. scrapeSite refusal — private targets + redirect re-validation
 * ================================================================== */

test("scrapeSite refuses a loopback URL even with a live server there", async () => {
  // A real server is listening — the guard must still refuse to connect.
  const server = http.createServer((_req, res) => res.end("<title>secret</title>"));
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const port = (server.address() as import("node:net").AddressInfo).port;
  try {
    const r = await scrapeSite(`http://127.0.0.1:${port}/`);
    assert.equal(r.ok, false);
    assert.match(r.error, /private|reserved/i);
  } finally {
    server.close();
  }
});

test("scrapeSite refuses cloud-metadata + non-http schemes", async () => {
  const meta = await scrapeSite("http://169.254.169.254/latest/meta-data/");
  assert.equal(meta.ok, false);
  assert.match(meta.error, /private|reserved/i);

  const file = await scrapeSite("file:///etc/passwd");
  assert.equal(file.ok, false);
  assert.match(file.error, /Refused|http/i);
});

test("redirect re-validation: a redirect Location at metadata is refused by the same validator scrapeSite applies per hop", async () => {
  // scrapeSite re-parses + re-validates each hop with exactly this chain.
  const loc = "http://169.254.169.254/";
  const next = parseHttpUrl(new URL(loc, "https://public.example.com/").toString());
  await assert.rejects(assertHostPublic(next.hostname), /private|reserved/i);
});

test("SSRF caps are sane (size ~2MB, timeout ~10s, few redirects)", () => {
  assert.equal(MAX_BYTES, 2_000_000);
  assert.equal(TIMEOUT_MS, 10_000);
  assert.ok(MAX_REDIRECTS <= 5 && MAX_REDIRECTS >= 1);
});

/* ================================================================== *
 * 4. Extraction parsing
 * ================================================================== */

test("extractFromHtml pulls name, tagline, services, contact, colour", () => {
  const html = `<!doctype html><html><head>
    <title>Bright Smiles Dental | Trusted family dentist</title>
    <meta property="og:site_name" content="Bright Smiles Dental">
    <meta name="description" content="Gentle dental care for the whole family.">
    <meta name="theme-color" content="#0a7c5a">
    <script>var x = "ignore me @not-an-email.com";</script>
    <style>.h{color:#ffffff}</style>
    </head><body>
    <h1>Welcome to Bright Smiles</h1>
    <h2>Teeth Whitening</h2>
    <h2>Dental Implants</h2>
    <ul><li>Emergency care</li><li>Invisalign</li></ul>
    <a href="mailto:hello@brightsmiles.example">Email</a>
    <a href="tel:+1 (555) 123-4567">Call</a>
    </body></html>`;
  const x = extractFromHtml(html);
  assert.equal(x.businessName, "Bright Smiles Dental");
  assert.equal(x.tagline, "Gentle dental care for the whole family.");
  assert.ok(x.services.includes("Teeth Whitening"));
  assert.ok(x.services.includes("Emergency care"));
  assert.ok(x.emails.includes("hello@brightsmiles.example"));
  assert.ok(x.phones.some((p) => p.includes("555")));
  assert.equal(x.colorHint, "#0a7c5a");
  assert.ok(!x.textSample.includes("ignore me"), "script content must be stripped");
});

test("extractFromHtml falls back to title segment for the name", () => {
  const x = extractFromHtml("<title>Joe's Diner - Best in town</title><h1>Menu</h1>");
  assert.equal(x.businessName, "Joe's Diner");
});

test("extractFromHtml decodes entities and de-dupes", () => {
  const x = extractFromHtml('<title>Ben &amp; Jerry&#39;s</title><h2>Ice Cream</h2><h2>Ice Cream</h2>');
  assert.equal(x.businessName, "Ben & Jerry's");
  assert.equal(x.services.filter((s) => s === "Ice Cream").length, 1);
});

test("extractionToPastedText composes a rewrite prompt without copying verbatim markers", () => {
  const text = extractionToPastedText({
    businessName: "Acme",
    tagline: "We do things",
    headings: ["A", "B"],
    services: ["X", "Y"],
    emails: ["a@b.co"],
    phones: ["+1 555 000 0000"],
    colorHint: "#123456",
    textSample: "Some page text.",
  });
  assert.ok(text.includes("Business: Acme"));
  assert.ok(text.includes("Services"));
  assert.ok(text.length <= 6000);
});

/* ================================================================== *
 * 5. Pipeline transitions
 * ================================================================== */

test("pipeline forward moves + close are allowed", () => {
  assert.ok(canTransition("LEAD", "CONTACTED"));
  assert.ok(canTransition("LEAD", "NEGOTIATING")); // multi-step forward
  assert.ok(canTransition("DEMO_SENT", "WON")); // close
  assert.ok(canTransition("NEGOTIATING", "LOST")); // close
});

test("pipeline back-one is allowed but back-two is not", () => {
  assert.ok(canTransition("DEMO_SENT", "CONTACTED")); // back one
  assert.equal(canTransition("NEGOTIATING", "LEAD"), false); // back three
});

test("pipeline terminal states reopen or flip", () => {
  assert.ok(isTerminal("WON"));
  assert.ok(isTerminal("LOST"));
  assert.ok(canTransition("WON", "NEGOTIATING")); // reopen
  assert.ok(canTransition("WON", "LOST")); // flip
  assert.ok(canTransition("LOST", "LEAD")); // reopen
});

test("pipeline rejects unknown stages, allows self", () => {
  assert.equal(canTransition("LEAD", "BOGUS" as never), false);
  assert.ok(canTransition("LEAD", "LEAD"));
  assert.equal(isDealStage("WON"), true);
  assert.equal(isDealStage("nope"), false);
  assert.equal(DEAL_STAGES.length, 6);
});

/* ================================================================== *
 * 6. Quote math
 * ================================================================== */

test("quoteTotals sums line items and applies tax on the subtotal", () => {
  const lines = [
    { description: "Build", quantity: 1, unitCents: 250000 },
    { description: "Hosting", quantity: 12, unitCents: 3000 },
  ];
  const t = quoteTotals(lines, 8);
  assert.equal(t.subtotalCents, 250000 + 36000); // 286000
  assert.equal(t.taxCents, Math.round(286000 * 0.08)); // 22880
  assert.equal(t.totalCents, 286000 + 22880);
});

test("quote math clamps negatives and absurd tax; integer cents only", () => {
  assert.equal(lineTotalCents({ description: "x", quantity: -5, unitCents: 100 }), 0);
  assert.equal(lineTotalCents({ description: "x", quantity: 2, unitCents: -100 }), 0);
  assert.equal(clampTaxRate(-4), 0);
  assert.equal(clampTaxRate(999), 100);
  assert.equal(clampTaxRate(8.4), 8);
  const t = quoteTotals([{ description: "x", quantity: 3, unitCents: 111 }], 0);
  assert.equal(t.subtotalCents, 333);
  assert.equal(t.taxCents, 0);
});

test("parsePriceToCents + formatCents round-trip", () => {
  assert.equal(parsePriceToCents("$1,250.50"), 125050);
  assert.equal(parsePriceToCents("1250"), 125000);
  assert.equal(parsePriceToCents("abc"), 0);
  assert.equal(formatCents(125000, "USD"), "$1,250.00");
  assert.equal(formatCents(333), "$3.33");
});

/* ================================================================== *
 * 7. Deploy bundle (pure, deterministic)
 * ================================================================== */

test("buildDeployBundle produces index.html + hard robots.txt and a byte count", () => {
  const b = buildDeployBundle({ slug: "joes-diner", renderedHtml: "<!doctype html><title>x</title>" });
  const paths = b.files.map((f) => f.path).sort();
  assert.deepEqual(paths, ["index.html", "robots.txt"]);
  const robots = b.files.find((f) => f.path === "robots.txt")!.content;
  assert.equal(robots, DEMO_ROBOTS_TXT);
  assert.match(robots, /Disallow: \//);
  assert.equal(b.intendedHost, "joes-diner.agency.revsports.ca");
  assert.ok(b.bytes > 0);
});

test("buildDeployBundle is deterministic", () => {
  const a = buildDeployBundle({ slug: "x", renderedHtml: "<html></html>" });
  const b = buildDeployBundle({ slug: "x", renderedHtml: "<html></html>" });
  assert.deepEqual(a, b);
});

